                                                               '// Own fixed arithmetic control. No tokens, '
                                                               'storage, calls or funds.\n'
                                                               'pragma solidity 0.8.30;\n'
                                                               'contract ConservationControl {\n'
                                                               '    function check(uint8 debit, uint8 '
                                                               'credit, uint8 quantity) public pure {\n'
                                                               '        require(debit <= 15 && credit <= 15 '
                                                               '&& quantity <= debit);\n'
                                                               '        uint16 finalDebit = uint16(debit) - '
                                                               'uint16(quantity);\n'
                                                               '        uint16 finalCredit = uint16(credit) '
                                                               '+ uint16(quantity) + 0;\n'
                                                               '        assert(false);\n'
                                                               '    }\n'
                                                               '}\n',
