                                                           'pragma solidity 0.8.30;\n'
                                                           'contract ConservationControl {\n'
                                                           '    function check(uint8 debit, uint8 credit, '
                                                           'uint8 quantity) public pure {\n'
                                                           '        require(false);\n'
                                                           '        uint16 finalDebit = uint16(debit) - '
                                                           'uint16(quantity);\n'
                                                           '        uint16 finalCredit = uint16(credit) + '
                                                           'uint16(quantity) + 0;\n'
                                                           '        assert(finalDebit + finalCredit == '
